func renderCurrentIARoutingEditorSetupStyleWithData(db *gorm.DB, r *http.Request, p model.Project, lang, readTable string, view productionNotificationReviewerView) string {
	html := renderCurrentIARoutingEditorMarkupWithData(db, r, p, lang, readTable, view)
	if scriptStart := strings.Index(html, `<script>`); scriptStart >= 0 {
		html = html[:scriptStart]
	}
	panelStart := strings.Index(html, `<section class="production-wfa-edit-panel" data-wfa-detail-panel`)
	if panelStart >= 0 {
		panelEnd := strings.Index(html[panelStart:], `</section>`)
		if panelEnd >= 0 {
			panelEnd += panelStart + len(`</section>`)
			panel := `<section id="production-wfa-detail-panel" class="production-wfa-edit-panel" data-wfa-detail-panel aria-live="polite" hidden><div class="production-wfa-edit-heading"><h4 data-wfa-title></h4><span>` + esc(t(lang, "WFA通知先", "WFA recipients")) + `</span></div><div class="production-wfa-recipient-row" data-wfa-automatic><span class="production-wfa-recipient-kind">` + esc(t(lang, "Supervisor", "Supervisor")) + `</span><span data-wfa-automatic-value>` + esc(t(lang, "確認中", "Checking")) + `</span></div><div class="production-wfa-recipient-row" data-wfa-additional><span class="production-wfa-recipient-kind">` + esc(t(lang, "追加通知先", "Additional recipients")) + `</span><ul data-wfa-target-list></ul><button type="button" class="btn-ghost production-wfa-add-target" data-wfa-add-target>+ ` + esc(t(lang, "追加", "Add")) + `</button></div></section>`
			html = html[:panelStart] + panel + html[panelEnd:]
		}
	}
	html = strings.Replace(html, `<div hidden data-editor-parking>`, `<div data-editor-parking>`, 1)
	html = strings.Replace(html, `<div class="table-wrap wizard-plan-table">`, `<div class="routing-list-scroll" data-routing-list-scroll><div class="table-wrap wizard-plan-table">`, 1)
	html = strings.Replace(html, `</tbody></table></div><div class="button-row production-routing-editor-actions">`, `</tbody></table></div></div><div class="button-row production-routing-editor-actions">`, 1)
	html = strings.Replace(html, `<div data-editor-parking>`, renderCurrentRoutingRowTemplate(lang, view.TaskTypes, model.ListProjectWebhooks(db, p.KitsuProjectID))+`<div data-editor-parking>`, 1)
	if noteStart := strings.Index(html, `<p class="field-help routing-destructive-note">`); noteStart >= 0 {
		if noteEnd := strings.Index(html[noteStart:], `</p>`); noteEnd >= 0 {
			noteEnd += noteStart + len(`</p>`)
			html = html[:noteStart] + html[noteEnd:]
		}
	}
	html = strings.Replace(html, `data-current-routing-form data-async-notification-apply`, `data-current-routing-form lang="`+esc(lang)+`" data-async-notification-apply`, 1)
	return html + currentRoutingEditorScript() + currentRoutingDeleteScript() + currentRecipientComboboxScript()
}

func renderCurrentRoutingRowTemplate(lang string, taskTypes []kitsu.TaskType, webhooks []model.ProjectWebhook) string {
	var types, typeOptions, destinations strings.Builder
	types.WriteString(`<option value="">` + esc(t(lang, "Task Typeを選択", "Select Task Type")) + `</option>`)
	for _, taskType := range taskTypes {
		types.WriteString(`<option value="` + esc(taskType.ID) + `" data-default-channel-name="` + esc(NormalizeTaskTypeChannelName(taskType.Name)) + `">` + esc(taskType.Name) + `</option>`)
		typeOptions.WriteString(`<button type="button" role="option" tabindex="-1" aria-selected="false" data-task-type-option="` + esc(taskType.ID) + `">` + esc(taskType.Name) + `</button>`)
	}
	for _, webhook := range webhooks {
		name := strings.TrimPrefix(strings.TrimSpace(webhook.ChannelName), "#")
		destinations.WriteString(`<option value="` + strconv.FormatUint(uint64(webhook.ID), 10) + `">#` + esc(name) + `</option>`)
	}
	destinations.WriteString(`<option value="__auto__">` + esc(t(lang, "自動作成", "Automatic")) + `</option><option value="__custom__">` + esc(t(lang, "カスタム...", "Custom...")) + `</option>`)
	return `<template data-routing-row-template><tr draggable="true" data-routing-row data-draft="true" data-task-type="" data-task-type-name="" data-default-channel-name="" data-existing-targets="W10=" tabindex="0" aria-controls="production-wfa-detail-panel" aria-selected="false" aria-expanded="false"><td><div class="routing-new-task-type" data-task-selector-wrap><select name="task_type_id" data-task-type-select hidden aria-hidden="true" tabindex="-1">` + types.String() + `</select><button type="button" class="recipient-combobox routing-task-type-combobox" role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-label="` + esc(t(lang, "Kitsuタスクタイプ", "Kitsu Task Type")) + `" data-task-type-combobox><span>` + esc(t(lang, "Task Typeを選択", "Select Task Type")) + `</span><span class="recipient-combobox-indicator" aria-hidden="true">▾</span></button><div class="recipient-listbox routing-task-type-listbox" role="listbox" aria-label="` + esc(t(lang, "Kitsuタスクタイプ", "Kitsu Task Type")) + `" data-task-type-listbox hidden>` + typeOptions.String() + `</div></div><button type="button" class="routing-select-task" data-select-task aria-pressed="false" aria-expanded="false" hidden><span class="routing-task-type-name">` + esc(t(lang, "Task Typeを選択", "Select Task Type")) + `</span><span class="routing-expand-indicator" aria-hidden="true"></span></button></td><td><div class="routing-destination-control"><select class="routing-destination-select" name="destination_mode" data-destination-control aria-label="` + esc(t(lang, "Discordチャンネル", "Discord Channel")) + `" disabled>` + destinations.String() + `</select><label class="routing-custom-channel" data-custom-channel-field hidden><span class="sr-only">` + esc(t(lang, "チャンネル名", "Channel name")) + `</span><input data-new-channel-name maxlength="100" autocomplete="off" disabled></label></div></td><td><details class="routing-row-menu"><summary aria-label="` + esc(t(lang, "行の操作", "Route actions")) + `">&#8942;</summary><div class="routing-row-menu-panel" role="menu"><button type="button" class="routing-remove" data-routing-remove role="menuitem">` + esc(t(lang, "通知対象から外す", "Remove from notifications")) + `</button></div></details></td></tr></template>`
}

